class Interface4GLegacy(object):
    """
    Keywords in this interface are legacy functions from 4G ute_admin

    Keywords aliasing via "connection", "alias" parameters, if no parameter provided it is "default"
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('connection', AdminConnection, name=__name__)

    def _extract_connection_from_4g(func):
        """ 4G uses alias parameter not connection """

        @wraps(func)
        def wrapper(self, *args, **kwargs):
            if "alias" in dict(kwargs):
                kwargs["connection"] = kwargs["alias"]
                kwargs.pop("alias")
            else:
                for arg, index in enumerate(list(args)):
                    if isinstance(arg, AdminConnection):
                        kwargs["connection"] = arg
                        args.pop(index)

            return func(self, *args, **kwargs)

        return wrapper

