    def setup_admin(self, bts_host='192.168.255.1', bts_port=443, username='Nemuadmin', password='nemuuser',
                    use_ssl=True, update_interval=5000, admin_api_log_dir='', bundle_path=None, remote_host=None,
                    remote_host_username='ute', remote_host_password='ute', remote_host_ssh_prompt='$ ', timeout=30,
                    alias="default", **kwargs):
        """
        Setup Admin API.

        :param string bts_host: BTS IP address.
        :param integer bts_port: AdminAPI port.
        :param string username: AdminAPI username.
        :param string password: AdminAPI password.
        :param boolean use_ssl: use SSL.
        :param integer update_interval: The minimum updates interval in [ms].
        :param string admin_api_log_dir: AdminAPI log directory.
        :param string bundle_path: Custom bundle.js path.
        :param string remote_host: NOT SUPPORTED remote host ip address for SSH tunneling. None means disabled SSH tunneling.
        :param string remote_host_username: NOT SUPPORTED Username for remote host SSH authentication. Default is 'ute'.
        :param string remote_host_password: NOT SUPPORTED Password for remote host SSH authentication. Default is 'ute'.
        :param string remote_host_ssh_prompt: NOT SUPPORTED SSH prompt received after logging in remote host. Default is '$ '.
        :param float timeout: NOT SUPPORTED Time to wait for Admin API setup.
        """
        return self.connect_to(bts_host=bts_host, bts_port=bts_port, username=username, password=password,
                               use_ssl=to_boolean(use_ssl), update_interval=update_interval,
                               admin_api_log_dir=admin_api_log_dir, bundle_path=bundle_path,
                               name=alias, **kwargs)

